 def runs(m):
  z=np.where(m)[0]; o=[]
  if len(z):
   q=np.split(z,np.where(np.diff(z)>1)[0]+1); o=[f'{a[0]}-{a[-1]}' for a in q if len(a)]
  return ','.join(o)
 if blue.any() or red.any(): print(f'{y:02} B[{runs(blue)}] O[{runs(red)}]')
